<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,nextTick,computed} from 'vue';import ProfessionalCard from './components/ProfessionalCard.vue';import NetworkBanner from './components/NetworkBanner.vue';import {api,ApiError} from './api';import {useSession} from './stores/session';import {useLive} from './composables/useLive';import {clearBookingDraft,draftKey,enqueueBooking,getBookingDraft,getBookingOutbox,saveBookingDraft,type BookingDraft,type BookingOutboxItem} from './offline/database';import {flush} from './offline/flush';import {specialties,dateLabel,timeLabel,type Professional,type Slot,type Page,type Appointment,type Notice,type AbAssignment} from './types';
const session=useSession(),live=useLive(),personalLive=useLive();
const view=ref<'search'|'appointments'>('search'),loading=ref(false),busy=ref(false),error=ref(''),success=ref('');
const q=ref(''),city=ref(''),specialty=ref(''),page=ref(0),total=ref(0),doctors=ref<Professional[]>([]),slots=ref<Record<number,Slot[]>>({});
const appointments=ref<Appointment[]>([]),notices=ref<Notice[]>([]),showNotices=ref(false),profile=ref<Professional|null>(null);
const authOpen=ref(false),register=ref(false),email=ref(''),password=ref(''),name=ref(''),authError=ref('');
const chosen=ref<{professional:Professional;slot:Slot}|null>(null),moveId=ref<number|null>(null),history=ref<{action:string;createdAt:string}[]|null>(null),cancelId=ref<number|null>(null);
const abPending=ref(true),abVariant=ref<'A'|'B'>('A'),abAssignmentId=ref<number|null>(null),abEnabled=ref(false),exposureSent=ref(false);
const networkNotice=ref<'queued'|'sent'|'login'|'account'|'conflict'|'retry'|null>(null),pendingBooking=ref<BookingOutboxItem|null>(null),rejectedDraft=ref<BookingDraft|null>(null),isOnline=ref(navigator.onLine);
const modal=ref<HTMLElement|null>(null);let priorFocus:HTMLElement|null=null;
let draftTimer:number|undefined,outboxFlusher:ReturnType<typeof flush>|undefined;
const alternativeSlots=computed(()=>rejectedDraft.value?slots.value[rejectedDraft.value.professionalId]?.filter(slot=>slot.id!==rejectedDraft.value?.slotId)??[]:[]);
function focusModal(){priorFocus=document.activeElement as HTMLElement;nextTick(()=>modal.value?.querySelector<HTMLElement>('button,input')?.focus())}
watch([authOpen,chosen,profile,history,cancelId,networkNotice],()=>{if(authOpen.value||chosen.value||profile.value||history.value||cancelId.value||networkNotice.value)focusModal();else priorFocus?.focus()});
function closeModal(){if(busy.value)return;authOpen.value=false;chosen.value=null;profile.value=null;history.value=null;cancelId.value=null;networkNotice.value=null;}
function trap(e:KeyboardEvent){if(e.key==='Escape')closeModal();if(e.key==='Tab'&&modal.value){const a=[...modal.value.querySelectorAll<HTMLElement>('button:not([disabled]),input,select,a[href]')];const first=a[0],last=a[a.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
let searchGeneration=0;
async function search(reset=false){if(reset)page.value=0;const generation=++searchGeneration;loading.value=true;error.value='';try{const result=await api<Page<Professional>>('/professionals?'+new URLSearchParams({q:q.value,city:city.value,specialty:specialty.value,page:String(page.value),size:'6'}));if(generation!==searchGeneration)return;doctors.value=result.items;total.value=result.total;await loadSlots();}catch(e){error.value=message(e)}finally{if(generation===searchGeneration)loading.value=false}}
async function loadSlots(){const entries=await Promise.all(doctors.value.map(async p=>[p.id,await api<Slot[]>(`/professionals/${p.id}/slots`)] as const));slots.value=Object.fromEntries(entries);}
function message(e:unknown){return e instanceof TypeError?'Connexion impossible. Vérifiez le réseau puis réessayez.':e instanceof Error?e.message:'Une erreur est survenue.'}
function isNetworkFailure(e:unknown){return e instanceof TypeError||(e instanceof DOMException&&e.name==='AbortError')}
function currentDraft(status:BookingDraft['status']='draft'):BookingDraft|null{if(!chosen.value||!session.user)return null;return {key:draftKey(session.user.id),userId:session.user.id,professionalId:chosen.value.professional.id,professionalName:chosen.value.professional.name,slotId:chosen.value.slot.id,startsAt:chosen.value.slot.startsAt,appointmentId:moveId.value,status,updatedAt:new Date().toISOString()}}
function scheduleDraftSave(){window.clearTimeout(draftTimer);if(!chosen.value||!session.user)return;draftTimer=window.setTimeout(()=>{const draft=currentDraft();if(draft)void saveBookingDraft(draft).catch(e=>{error.value=message(e)})},500)}
watch([chosen,moveId,()=>session.user?.id],scheduleDraftSave);
async function refreshAfterBooking(){try{await Promise.all([refreshAppointments(),refreshNotices(),loadSlots()]);view.value='appointments'}catch(e){console.error('Reservation confirmed, but refreshing the page data failed.',e)}}
function startOutboxFlush(){outboxFlusher?.stop();outboxFlusher=flush({send:async item=>{if(!session.user)throw new ApiError('Reconnectez-vous pour envoyer votre réservation.',401);if(session.user.id!==item.userId)throw new ApiError('Cette réservation appartient à un autre compte.',403,'ACCOUNT_MISMATCH');try{const appointment=await api<Appointment>('/appointments',{method:'POST',headers:{'Idempotency-Key':item.idemKey},body:JSON.stringify({slotId:item.slotId})});return {status:201,appointment}}catch(e){if(e instanceof ApiError)return {status:e.status,code:e.code};throw e}},sent:async item=>{await clearBookingDraft(item.userId);pendingBooking.value=null;rejectedDraft.value=null;networkNotice.value='sent';success.value='Rendez-vous confirmé';await refreshAfterBooking()},rejected:async(_item,draft)=>{pendingBooking.value=null;rejectedDraft.value=draft??null;networkNotice.value='conflict';await loadSlots()},failed:(_item,e)=>{if(isNetworkFailure(e)){isOnline.value=navigator.onLine;networkNotice.value='queued'}else if(e instanceof ApiError&&e.status===401)networkNotice.value='login';else if(e instanceof ApiError&&e.code==='ACCOUNT_MISMATCH')networkNotice.value='account';else{error.value=message(e);networkNotice.value='retry'}}})}
async function queueBooking(selected:{professional:Professional;slot:Slot},idemKey:string){if(!session.user)throw new Error('Connectez-vous pour enregistrer cette réservation.');const draft:BookingDraft={key:draftKey(session.user.id),userId:session.user.id,professionalId:selected.professional.id,professionalName:selected.professional.name,slotId:selected.slot.id,startsAt:selected.slot.startsAt,appointmentId:null,status:'draft',updatedAt:new Date().toISOString()};const item:BookingOutboxItem={idemKey,userId:session.user.id,slotId:selected.slot.id,appointmentId:null,createdAt:new Date().toISOString()};await enqueueBooking(draft,item);window.clearTimeout(draftTimer);pendingBooking.value=item;rejectedDraft.value=null;chosen.value=null;moveId.value=null;networkNotice.value='queued';void outboxFlusher?.run()}
async function restoreOfflineDraft(){if(!session.user)return;const saved=await getBookingDraft(session.user.id);if(!saved)return;if(saved.status==='pending'){pendingBooking.value=(await getBookingOutbox()).find(item=>item.idemKey===saved.idemKey)??null;if(pendingBooking.value)networkNotice.value='queued';return}if(saved.status==='rejected'){rejectedDraft.value=saved;networkNotice.value='conflict';const doctor=doctors.value.find(item=>item.id===saved.professionalId);if(doctor){const available=await api<Slot[]>(`/professionals/${doctor.id}/slots`);slots.value={...slots.value,[doctor.id]:available}}return}const doctor=doctors.value.find(item=>item.id===saved.professionalId);const slot=slots.value[saved.professionalId]?.find(item=>item.id===saved.slotId);if(doctor&&slot){chosen.value={professional:doctor,slot};moveId.value=saved.appointmentId}}
function chooseAlternative(slot:Slot){const saved=rejectedDraft.value;if(!saved)return;const doctor=doctors.value.find(item=>item.id===saved.professionalId);if(!doctor)return;chosen.value={professional:doctor,slot};moveId.value=saved.appointmentId;rejectedDraft.value=null;networkNotice.value=null}
function onNetworkOffline(){isOnline.value=false}
async function onNetworkOnline(){isOnline.value=true;try{if(!session.user)await session.load();await restoreOfflineDraft()}catch(e){error.value=message(e)}if(rejectedDraft.value&&session.user){try{const available=await api<Slot[]>(`/professionals/${rejectedDraft.value.professionalId}/slots`);slots.value={...slots.value,[rejectedDraft.value.professionalId]:available}}catch(e){error.value=message(e)}}void outboxFlusher?.run()}
async function loadAbAssignment(){const controller=new AbortController(),timeout=window.setTimeout(()=>controller.abort(),3000);try{const assignment=await api<AbAssignment>('/ab/assignment',{signal:controller.signal});abVariant.value=assignment.variant==='B'?'B':'A';abAssignmentId.value=assignment.id;abEnabled.value=assignment.enabled;}catch(e){abVariant.value='A';abAssignmentId.value=null;abEnabled.value=false;console.warn('A/B assignment unavailable; using variant A.',e)}finally{window.clearTimeout(timeout);abPending.value=false}}
function exposeIfAvailable(){if(abPending.value||!abEnabled.value||abAssignmentId.value===null||exposureSent.value)return;exposureSent.value=true;api('/ab/exposure',{method:'POST',body:JSON.stringify({id:abAssignmentId.value})}).catch(e=>console.error('A/B exposure could not be recorded.',e))}
async function refreshAppointments(){if(!session.user)return;appointments.value=await api<Appointment[]>('/appointments');}
async function refreshNotices(){if(session.user)notices.value=await api<Notice[]>('/notifications');}
function choose(professional:Professional,slot:Slot){success.value='';error.value='';profile.value=null;chosen.value={professional,slot};if(!session.user){authOpen.value=true;authError.value='';}}
async function authenticate(){busy.value=true;authError.value='';try{if(register.value)await api('/register',{method:'POST',body:JSON.stringify({name:name.value,email:email.value,password:password.value})});await session.login(email.value,password.value);authOpen.value=false;password.value='';await refreshAppointments();void outboxFlusher?.run()}catch(e){authError.value=message(e)}finally{busy.value=false}}
async function confirm(){if(!chosen.value)return;if(!session.user){openAuth();return}if(pendingBooking.value){error.value='Une réservation est déjà en attente d’envoi. Réessayez après son traitement.';return}const selected=chosen.value,appointmentId=moveId.value,idemKey=crypto.randomUUID();if(appointmentId!==null&&!isOnline.value){error.value='Le déplacement nécessite une connexion. Votre rendez-vous actuel reste conservé.';return}if(!isOnline.value){try{await queueBooking(selected,idemKey)}catch(e){error.value=message(e)}return}busy.value=true;error.value='';try{await api<Appointment>(appointmentId?`/appointments/${appointmentId}`:'/appointments',{method:appointmentId?'PATCH':'POST',headers:appointmentId?{}:{'Idempotency-Key':idemKey},body:JSON.stringify({slotId:selected.slot.id})});window.clearTimeout(draftTimer);await clearBookingDraft(session.user.id);success.value=appointmentId?'Votre rendez-vous a été déplacé.':'Rendez-vous confirmé';chosen.value=null;moveId.value=null;await refreshAfterBooking()}catch(e){if(isNetworkFailure(e)&&appointmentId===null){try{await queueBooking(selected,idemKey)}catch(queueError){error.value=message(queueError)}return}if(e instanceof ApiError&&e.status===409&&e.code==='SLOT_TAKEN'&&appointmentId===null){const rejected=currentDraft('rejected');if(rejected){window.clearTimeout(draftTimer);await saveBookingDraft(rejected);rejectedDraft.value=rejected;chosen.value=null;networkNotice.value='conflict';await loadSlots();return}}error.value=message(e)}finally{busy.value=false}}
async function cancel(){if(cancelId.value===null)return;busy.value=true;try{await api(`/appointments/${cancelId.value}/cancel`,{method:'POST'});cancelId.value=null;success.value='Votre rendez-vous a été annulé.';await refreshAppointments();await loadSlots();await refreshNotices();}catch(e){error.value=message(e)}finally{busy.value=false}}
async function move(a:Appointment){moveId.value=a.id;q.value=a.professionalName;city.value='';specialty.value='';view.value='search';await search(true);success.value='Choisissez un nouveau créneau. Votre réservation actuelle reste conservée jusqu’à confirmation.';}
async function showHistory(id:number){try{history.value=await api(`/appointments/${id}/history`)}catch(e){error.value=message(e)}}
async function logout(){try{await session.logout();personalLive.close();notices.value=[];appointments.value=[];showNotices.value=false;view.value='search';moveId.value=null;}catch(e){error.value=message(e)}}
function openAuth(){authOpen.value=true;authError.value='';register.value=false;}
function myAppointments(){if(!session.user){openAuth();return;}view.value='appointments';refreshAppointments().catch(e=>error.value=message(e));}
watch(()=>session.user, user=>{personalLive.close();if(user){refreshNotices().catch(()=>{});personalLive.connect('/api/notifications/events',()=>{refreshNotices().catch(()=>{});refreshAppointments().catch(()=>{})},'notifications-changed')}});
onMounted(async()=>{window.addEventListener('offline',onNetworkOffline);window.addEventListener('online',onNetworkOnline);void loadAbAssignment();await search();try{await session.load()}catch(e){error.value=message(e)}try{await restoreOfflineDraft()}catch(e){error.value=message(e)}startOutboxFlush();live.connect('/api/events',()=>loadSlots().catch(()=>{}));});
onUnmounted(()=>{window.clearTimeout(draftTimer);window.removeEventListener('offline',onNetworkOffline);window.removeEventListener('online',onNetworkOnline);outboxFlusher?.stop()});
</script>
<template>
 <a href="#main" class="skip">Aller au contenu</a><NetworkBanner :online="isOnline"/>
 <header class="header"><button class="brand" @click="view='search';moveId=null">MediSlot<span class="brand-dot">.</span></button><nav aria-label="Navigation principale"><button :class="{active:view==='search'}" @click="view='search'">Trouver un praticien</button><button :class="{active:view==='appointments'}" @click="myAppointments">Mes rendez-vous</button><button v-if="session.user" @click="showNotices=!showNotices" :aria-expanded="showNotices">Notifications <span class="count">{{notices.length}}</span></button><button v-if="!session.user" class="login" @click="openAuth">Se connecter</button><button v-else class="login" @click="logout">{{session.user.name.split(' ')[0]}} · Déconnexion</button></nav></header>
 <section v-if="view==='search'" class="hero"><div class="hero-inner"><p class="eyebrow">VOTRE PROCHAIN RENDEZ-VOUS</p><h1>Trouvez le bon praticien.<br>Prenez un moment pour vous.</h1><p class="hero-copy">Un professionnel près de chez vous, au créneau qui vous convient.</p><form class="searchbar" @submit.prevent="search(true)"><label><span>Nom du praticien</span><input v-model="q" placeholder="Nom, praticien…" autocomplete="off"></label><label><span>Spécialité</span><select v-model="specialty"><option value="">Toutes les spécialités</option><option v-for="(label,key) in specialties" :key="key" :value="key">{{label}}</option></select></label><label><span>Ville</span><input v-model="city" placeholder="Paris, Lyon…" autocomplete="address-level2"></label><button type="submit" :disabled="loading">{{loading?'Recherche…':'Rechercher'}} <span aria-hidden="true">→</span></button></form><div class="hero-bottom"><span>Des créneaux visibles en quelques clics</span><span class="live" :class="{offline:!live.connected.value}"><i></i>{{live.connected.value?'Disponibilités en direct':'Reconnexion du direct…'}}</span></div></div></section>
 <main id="main" class="main">
  <div v-if="showNotices&&session.user" class="notices"><div class="section-title"><h2>Vos notifications</h2><button class="text-button" @click="showNotices=false">Fermer</button></div><p v-if="!notices.length">Aucune notification pour le moment.</p><p v-for="n in notices" :key="n.id">{{n.message}} <small>{{dateLabel(n.createdAt)}}</small></p></div>
  <p v-if="error" role="alert" class="alert error">{{error}} <button class="text-button" @click="search()">Réessayer</button></p><p v-if="success" role="status" class="alert success">{{success}}</p>
  <template v-if="view==='search'"><div class="section-title"><div><p class="eyebrow dark">VOTRE RECHERCHE</p><h2>{{total}} praticien{{total>1?'s':''}} à découvrir</h2></div><span class="subtle">Rendez-vous au cabinet</span></div>
   <div v-if="moveId" class="move-banner">Déplacement du rendez-vous n° {{moveId}} <button class="text-button" @click="moveId=null;success=''">Abandonner le déplacement</button></div>
   <div v-if="loading" class="loading" role="status">Nous recherchons vos prochains créneaux…</div><div v-else-if="!doctors.length" class="empty"><h3>Aucun praticien ne correspond à cette recherche</h3><p>Essayez une autre ville ou une spécialité différente.</p><button class="primary" @click="q='';city='';specialty='';search(true)">Voir tous les praticiens</button></div>
   <div v-else class="results"><div class="cards"><ProfessionalCard v-for="p in doctors" :key="p.id" :professional="p" :slots="slots[p.id]||[]" :variant="abPending?null:abVariant" :expose-if-available="exposeIfAvailable" @choose="choose" @profile="profile=$event"/></div><aside class="help"><span class="help-icon" aria-hidden="true">+</span><h2>Votre rendez-vous,<br>en toute simplicité.</h2><ol><li>Choisissez votre praticien.</li><li>Sélectionnez un créneau.</li><li>Retrouvez la confirmation dans votre espace.</li></ol><hr><p>Un changement de programme ? Vous pouvez déplacer ou annuler votre rendez-vous depuis votre espace.</p><p class="demo-note">Démonstration pédagogique.<br>Praticiens et données fictifs.</p></aside></div>
   <div v-if="total>6" class="pagination"><button :disabled="page===0" @click="page--;search()">Précédent</button><span>Page {{page+1}}</span><button :disabled="(page+1)*6>=total" @click="page++;search()">Suivant</button></div>
  </template>
  <template v-else><div class="section-title"><div><p class="eyebrow dark">VOTRE ESPACE</p><h1>Mes rendez-vous</h1></div><button class="primary" @click="view='search'">Prendre rendez-vous</button></div><p v-if="!appointments.length" class="empty">Vous n’avez pas encore de rendez-vous.</p><article v-for="a in appointments" :key="a.id" class="appointment"><div class="appointment-date"><strong>{{dateLabel(a.startsAt)}}</strong><span>{{timeLabel(a.startsAt)}}</span></div><div class="appointment-person"><h2>{{a.professionalName}}</h2><p>{{specialties[a.specialty]}} · {{a.city}}</p><span class="status" :class="{cancelled:a.status==='CANCELLED'}">{{a.status==='CONFIRMED'?'Confirmé':'Annulé'}}</span></div><div class="appointment-actions"><button v-if="a.status==='CONFIRMED'" @click="move(a)">Déplacer</button><button v-if="a.status==='CONFIRMED'" class="danger-link" @click="cancelId=a.id">Annuler</button><button class="text-button" @click="showHistory(a.id)">Historique</button></div></article></template>
 </main><footer><span class="brand footer-brand">MediSlot.</span><p>Votre parcours de soins, simplement.</p><small>Application de formation · Données fictives · Horaires Europe/Paris</small></footer>
 <div v-if="authOpen||chosen||profile||history||cancelId||networkNotice" class="overlay" @click.self="closeModal"><section ref="modal" class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" @keydown="trap"><button class="close" aria-label="Fermer" @click="closeModal">×</button>
  <template v-if="networkNotice"><p class="eyebrow dark">{{networkNotice==='sent'?'ENVOI TERMINÉ':networkNotice==='conflict'?'CRÉNEAU INDISPONIBLE':'ÉTAT DE LA CONNEXION'}}</p><h2 id="modal-title">{{networkNotice==='sent'?'Rendez-vous confirmé':networkNotice==='conflict'?'Le créneau n’est plus disponible':networkNotice==='account'?'Connectez-vous avec le bon compte':networkNotice==='login'?'Reconnectez-vous pour envoyer la demande':networkNotice==='retry'?'Envoi non confirmé':'Vous êtes hors ligne'}}</h2><p v-if="networkNotice==='queued'">En attente d'envoi : le créneau n'est pas encore réservé.</p><p v-if="networkNotice==='queued'">Votre brouillon est enregistré dans IndexedDB sur cet appareil. Il sera envoyé au retour du réseau.</p><p v-else-if="networkNotice==='sent'">Le serveur a confirmé la réservation. La demande a été envoyée une seule fois grâce à sa clé d’idempotence.</p><p v-else-if="networkNotice==='conflict'">La demande n’a pas été créée. Votre brouillon est conservé ; choisissez un autre créneau du même médecin.</p><div v-if="networkNotice==='conflict'&&alternativeSlots.length" class="alternative-slots"><button v-for="slot in alternativeSlots" :key="slot.id" class="slot" @click="chooseAlternative(slot)">{{dateLabel(slot.startsAt)}} · {{timeLabel(slot.startsAt)}}</button></div><p v-else-if="networkNotice==='conflict'">Aucun autre créneau libre n’est disponible pour ce médecin pour le moment.</p><p v-else-if="networkNotice==='account'">La demande en attente est liée à un autre compte. Elle ne sera pas envoyée avec le compte actuel.</p><p v-else-if="networkNotice==='login'">Votre demande reste conservée dans ce navigateur. Connectez-vous avec le compte qui l’a créée pour l’envoyer.</p><p v-else-if="networkNotice==='retry'">{{error}} La demande reste conservée dans ce navigateur.</p><button v-if="pendingBooking&&isOnline&&(networkNotice==='queued'||networkNotice==='retry'||networkNotice==='login')" class="primary wide" :disabled="busy" @click="void outboxFlusher?.run()">{{busy?'Envoi…':'Réessayer maintenant'}}</button><button class="text-button" @click="closeModal">Fermer</button></template>
  <template v-else-if="authOpen"><p class="eyebrow dark">VOTRE ESPACE MEDISLOT</p><h2 id="modal-title">{{register?'Créer votre compte':'Heureux de vous retrouver'}}</h2><p class="subtle">Connectez-vous pour confirmer et retrouver vos rendez-vous.</p><form class="auth-form" @submit.prevent="authenticate"><label v-if="register">Votre nom<input v-model="name" required maxlength="120" autocomplete="name"></label><label>Adresse e-mail<input v-model="email" type="email" required autocomplete="email"></label><label>Mot de passe<input v-model="password" type="password" required :minlength="register?12:1" maxlength="72" :autocomplete="register?'new-password':'current-password'"></label><p v-if="authError" role="alert" class="error-text">{{authError}}</p><button class="primary" :disabled="busy">{{busy?'Connexion…':register?'Créer mon compte':'Se connecter'}}</button></form><button class="text-button" @click="register=!register">{{register?'J’ai déjà un compte':'Créer un compte'}}</button><details class="demo-credentials"><summary>Compte de démonstration</summary><p>patient@medislot.test<br>MediSlot-demo-2026!</p></details></template>
  <template v-else-if="chosen"><p class="eyebrow dark">DERNIÈRE ÉTAPE</p><h2 id="modal-title">Confirmer votre rendez-vous</h2><div class="booking-summary"><h3>{{chosen.professional.name}}</h3><p>{{specialties[chosen.professional.specialty]}}</p><strong>{{dateLabel(chosen.slot.startsAt)}} à {{timeLabel(chosen.slot.startsAt)}}</strong><p>{{chosen.professional.address}}, {{chosen.professional.city}}</p></div><p class="subtle">Le créneau sera réservé après confirmation du serveur. Une autre personne peut encore le sélectionner entre-temps.</p><p v-if="error" class="error-text" role="alert">{{error}}</p><button class="primary wide" :disabled="busy" @click="confirm">{{busy?'Confirmation…':moveId?'Confirmer le déplacement':'Confirmer le rendez-vous'}}</button></template>
  <template v-else-if="profile"><p class="eyebrow dark">VOTRE PRATICIEN</p><h2 id="modal-title">{{profile.name}}</h2><p class="specialty">{{specialties[profile.specialty]}}</p><p>{{profile.bio}}</p><h3>Le cabinet</h3><p>{{profile.address}}, {{profile.city}}</p><h3>Consultation</h3><p>{{profile.fee}} € · 30 minutes · Au cabinet</p><button class="primary wide" @click="profile=null">Voir les disponibilités</button></template>
  <template v-else-if="history"><h2 id="modal-title">Historique du rendez-vous</h2><ol class="timeline"><li v-for="(h,i) in history" :key="i"><strong>{{({CREATED:'Réservation confirmée',RESCHEDULED:'Rendez-vous déplacé',CANCELLED:'Rendez-vous annulé'} as Record<string,string>)[h.action]||h.action}}</strong><p>{{dateLabel(h.createdAt)}} à {{timeLabel(h.createdAt)}}</p></li></ol></template>
  <template v-else-if="cancelId"><h2 id="modal-title">Annuler ce rendez-vous ?</h2><p>Le créneau sera remis à disposition. Vous pourrez prendre un autre rendez-vous quand vous le souhaitez.</p><button class="primary wide" :disabled="busy" @click="cancel">Confirmer l’annulation</button><button class="text-button" @click="cancelId=null">Conserver mon rendez-vous</button></template>
 </section></div>
</template>
